  To find the highest common ancestor (HCA) of two nodes in a binary tree, you can use a recursive approach. Here is an example of how to do this in JavaScript:
```
function hca(a, b) {
  // Base case: If either node is null, return null
  if (a === null || b === null) {
    return null;
  }

  // Find the common ancestor by recursively traversing the tree
  let current = a;
  while (current !== null && current !== b) {
    current = current.parent;
  }

  // If we reached the same node, return it
  if (current === b) {
    return current;
  }

  // If we didn't find a common ancestor, return null
  return null;
}

// Examples
console.log(hca(null, null)); // null
console.log(hca(1, 2)); // null
console.log(hca(1, 1)); // 1
console.log(hca(1, 3)); // 2
```
